<?php
namespace App\Services;
final class SigningService { public function sign(array $payload):string { $private=$this->decode(config('office.signing_private_key')); if(!$private) throw new \RuntimeException('Central signing key is not configured.'); return sodium_bin2base64(sodium_crypto_sign_detached($this->canonical($payload),$private),SODIUM_BASE64_VARIANT_URLSAFE_NO_PADDING); } public function publicKey():string { return (string)config('office.signing_public_key'); } public static function generate():array { $pair=sodium_crypto_sign_keypair(); return ['private'=>sodium_bin2base64(sodium_crypto_sign_secretkey($pair),SODIUM_BASE64_VARIANT_URLSAFE_NO_PADDING),'public'=>sodium_bin2base64(sodium_crypto_sign_publickey($pair),SODIUM_BASE64_VARIANT_URLSAFE_NO_PADDING)]; } private function decode(?string $key):string|false { return $key?sodium_base642bin($key,SODIUM_BASE64_VARIANT_URLSAFE_NO_PADDING):false; } private function canonical(array $payload):string { ksort($payload); return json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR); } }
